package local.pitv;
import android.content.*;import android.graphics.*;import android.text.*;import android.view.*;import java.util.*;
final class ProgramGuideView extends View {
 interface Host {void selected(GuideModel.Channel c,GuideModel.Program p);void activate(GuideModel.Channel c,GuideModel.Program p);Bitmap logo(String url,Runnable ready);}
 Runnable menuAction,optionsAction,topAction;final List<GuideModel.Channel> channels;final Host host;TextPaint ink=new TextPaint(Paint.ANTI_ALIAS_FLAG);Paint fill=new Paint(Paint.ANTI_ALIAS_FLAG);int row=0,firstRow=0;long selectedTime=System.currentTimeMillis(),window=selectedTime/(30*GuideModel.MINUTE)*(30*GuideModel.MINUTE);long span=2*GuideModel.HOUR;float channelWidth,header,rowHeight;boolean followNow=true;Runnable ticker=new Runnable(){public void run(){if(followNow){selectedTime=System.currentTimeMillis();keepVisible();notifySelection();}else invalidate();postDelayed(this,30000);}};
 ProgramGuideView(Context context,List<GuideModel.Channel> data,Host h){super(context);channels=data;host=h;setFocusable(true);setFocusableInTouchMode(true);setBackgroundColor(Color.TRANSPARENT);channelWidth=dp(220);header=dp(30);rowHeight=dp(40);notifySelection();}
 float dp(int n){return TvStyle.dp(getContext(),n);}int visibleRows(){return Math.max(1,(int)((getHeight()-header)/rowHeight));}
 GuideModel.Program program(){return channels.isEmpty()?null:GuideModel.at(channels.get(row),selectedTime);}
 void notifySelection(){if(channels.isEmpty())return;GuideModel.Channel c=channels.get(row);GuideModel.Program p=program();host.selected(c,p);setContentDescription(c.name+" / "+(p==null?"No schedule supplied":p.title+" / "+clock(p.start)+" to "+clock(p.end)));invalidate();}
 String clock(long time){return android.text.format.DateFormat.getTimeFormat(getContext()).format(new Date(time));}
 void jump(long time){followNow=Math.abs(time-System.currentTimeMillis())<60000;selectedTime=time;window=time/(30*GuideModel.MINUTE)*(30*GuideModel.MINUTE);notifySelection();}
 void keepVisible(){if(row<firstRow)firstRow=row;if(row>=firstRow+visibleRows())firstRow=row-visibleRows()+1;if(selectedTime<window)window=selectedTime/(30*GuideModel.MINUTE)*(30*GuideModel.MINUTE);if(selectedTime>=window+span)window=selectedTime-span+30*GuideModel.MINUTE;}
 @Override public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_MENU&&optionsAction!=null){optionsAction.run();return true;}if(channels.isEmpty()){if(key==KeyEvent.KEYCODE_DPAD_LEFT&&menuAction!=null){menuAction.run();return true;}return super.onKeyDown(key,event);}if(key==KeyEvent.KEYCODE_DPAD_UP){if(row==0){if(topAction!=null){topAction.run();return true;}return super.onKeyDown(key,event);}row--;}else if(key==KeyEvent.KEYCODE_DPAD_DOWN){if(row<channels.size()-1)row++;}else if(key==KeyEvent.KEYCODE_DPAD_LEFT&&menuAction!=null&&selectedTime<=System.currentTimeMillis()+GuideModel.MINUTE){menuAction.run();return true;}else if(key==KeyEvent.KEYCODE_DPAD_LEFT){followNow=false;selectedTime=GuideModel.move(channels.get(row),selectedTime,-1);}else if(key==KeyEvent.KEYCODE_DPAD_RIGHT){followNow=false;selectedTime=GuideModel.move(channels.get(row),selectedTime,1);}else if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(optionsAction!=null){event.startTracking();return true;}host.activate(channels.get(row),program());return true;}else if(key==KeyEvent.KEYCODE_CHANNEL_UP)row=Math.max(0,row-visibleRows());else if(key==KeyEvent.KEYCODE_CHANNEL_DOWN)row=Math.min(channels.size()-1,row+visibleRows());else return super.onKeyDown(key,event);keepVisible();notifySelection();return true;}
 @Override public boolean onKeyLongPress(int key,KeyEvent event){if(optionsAction!=null&&(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER)){optionsAction.run();return true;}return super.onKeyLongPress(key,event);}
 @Override public boolean onKeyUp(int key,KeyEvent event){if(optionsAction!=null&&(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER)){if(!event.isCanceled()&&!channels.isEmpty())host.activate(channels.get(row),program());return true;}return super.onKeyUp(key,event);}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()!=android.view.MotionEvent.ACTION_UP)return true;int index=firstRow+(int)((e.getY()-header)/rowHeight);if(e.getY()<header||index>=channels.size()||index<0)return true;long time=window+(long)((Math.max(channelWidth,e.getX())-channelWidth)/Math.max(1,getWidth()-channelWidth)*span);boolean same=index==row&&GuideModel.at(channels.get(index),time)==program();row=index;followNow=false;selectedTime=time;requestFocus();notifySelection();if(e.getX()<channelWidth||same)host.activate(channels.get(row),program());return true;}
 @Override protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);removeCallbacks(ticker);if(visibility==VISIBLE)postDelayed(ticker,30000);}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();removeCallbacks(ticker);postDelayed(ticker,30000);}
 @Override protected void onDetachedFromWindow(){removeCallbacks(ticker);super.onDetachedFromWindow();}
 void rect(Canvas canvas,float x,float y,float w,float h,int color){fill.setColor(color);canvas.drawRect(x,y,x+w,y+h,fill);}
 void text(Canvas canvas,String text,float x,float y,float width,int color,int size){ink.setColor(color);ink.setTextSize(dp(size));canvas.drawText(TextUtils.ellipsize(text==null?"":text,ink,Math.max(1,width),TextUtils.TruncateAt.END).toString(),x,y,ink);}
 @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float width=getWidth(),timeline=width-channelWidth;long now=System.currentTimeMillis();rect(canvas,0,0,channelWidth,header,0x00151e33);text(canvas,android.text.format.DateFormat.format("EEE, MMM d",new Date(window)).toString(),dp(10),dp(20),channelWidth-dp(20),0xffa8afc7,11);int slots=Math.max(1,(int)(span/(30*GuideModel.MINUTE)));for(int n=0;n<=slots;n++){float x=channelWidth+timeline*n/(float)slots;rect(canvas,x,0,1,getHeight(),0xff27314b);text(canvas,clock(window+n*30*GuideModel.MINUTE),x+dp(5),dp(20),timeline/slots-dp(5),0xffa8afc7,11);}for(int index=firstRow;index<Math.min(channels.size(),firstRow+visibleRows()+1);index++){GuideModel.Channel ch=channels.get(index);float y=header+(index-firstRow)*rowHeight;rect(canvas,0,y,channelWidth-dp(2),rowHeight-dp(2),index==row?0xff23566f:0xff192126);Bitmap logo=ch.logo==null?null:host.logo(ch.logo,()->invalidate());float textX=dp(10);if(logo!=null){canvas.drawBitmap(logo,null,new RectF(dp(8),y+dp(6),dp(33),y+rowHeight-dp(6)),fill);textX=dp(40);}text(canvas,String.format(Locale.ROOT,"%03d  %s",index+1,ch.name),textX,y+dp(23),channelWidth-textX-dp(7),index==row?0xffffffff:TvStyle.INK,11);rect(canvas,channelWidth,y,timeline,rowHeight-dp(2),index==row?0x55355769:0x22101827);java.util.HashSet<Long> drawnStarts=new java.util.HashSet<>();for(int pi=0;pi<ch.programs.size();pi++){GuideModel.Program p=ch.programs.get(pi);if(!drawnStarts.add(p.start))continue;long visualEnd=p.end;for(int next=pi+1;next<ch.programs.size();next++){long start=ch.programs.get(next).start;if(start>p.start){visualEnd=Math.min(visualEnd,start);break;}}if(visualEnd<=window||p.start>=window+span)continue;float x=channelWidth+timeline*GuideModel.fraction(p.start,window,span),end=channelWidth+timeline*GuideModel.fraction(visualEnd,window,span);boolean selected=index==row&&p==program(),live=p.start<=now&&p.end>now;rect(canvas,x+dp(1),y+dp(1),Math.max(1,end-x-dp(2)),rowHeight-dp(4),index==row?0xff2c4350:live?0xff27353d:0xff1c252b);int save=canvas.save();canvas.clipRect(x+dp(2),y,end-dp(2),y+rowHeight-dp(3));text(canvas,p.title,x+dp(7),y+dp(23),end-x-dp(14),TvStyle.INK,12);canvas.restoreToCount(save);}}if(now>=window&&now<window+span){float x=channelWidth+timeline*GuideModel.fraction(now,window,span);rect(canvas,x,header,dp(1),getHeight()-header,0xff25aaff);fill.setColor(0xff25aaff);Path triangle=new Path();triangle.moveTo(x-dp(4),header-dp(5));triangle.lineTo(x+dp(4),header-dp(5));triangle.lineTo(x,header);triangle.close();canvas.drawPath(triangle,fill);}if(channels.isEmpty())text(canvas,"No channels in this group",dp(20),header+dp(40),width-dp(40),TvStyle.INK,16);}
}
